<?php

namespace App\Support\BlockTypes;

use App\Modules\BlockTypes\Contracts\BlockTypeVocabulary;
use InvalidArgumentException;

/**
 * Builds, from every `block-types/{key}/v{N}/schema.json`, the PHP value object `Contracts/{Key}Slots.php` of the BlockTypes module and the
 * TypeScript type `resources/js/types/block-types.ts`. `schema.json` is the single source; `dashflow:block-types --check` fails when a generated file differs.
 */
final class BlockTypeGenerator
{
    public const TS_OUTPUT = 'resources/js/types/block-types.ts';

    public const PHP_DIR = 'app/Modules/BlockTypes/Contracts';

    /**
     * @return array<string, array<string, mixed>> "key@version" => decoded schema.json
     */
    public static function discover(string $root): array
    {
        $schemas = [];
        $files = glob(rtrim($root, '/').'/*/v*/schema.json') ?: [];
        sort($files);

        foreach ($files as $file) {
            $schema = json_decode((string) file_get_contents($file), true);

            if (! is_array($schema) || ! is_string($schema['key'] ?? null) || ! is_int($schema['contractVersion'] ?? null)) {
                throw new InvalidArgumentException("{$file} is not a valid schema.json (key and contractVersion are required).");
            }

            $schemas["{$schema['key']}@{$schema['contractVersion']}"] = $schema;
        }

        return $schemas;
    }

    /**
     * @param  array<string, array<string, mixed>>  $schemas
     * @return array<string, string> repo-relative path => content
     */
    public function render(array $schemas): array
    {
        $out = [self::TS_OUTPUT => $this->typescript($schemas)];

        foreach ($schemas as $schema) {
            $out[self::PHP_DIR.'/'.$this->className($schema).'.php'] = $this->php($schema);
        }

        ksort($out);

        return $out;
    }

    /** @param  array<string, mixed>  $schema */
    private function className(array $schema): string
    {
        return str_replace(' ', '', ucwords(str_replace('-', ' ', (string) $schema['key']))).'Slots'.((int) $schema['contractVersion'] === 1 ? '' : 'V'.$schema['contractVersion']);
    }

    /** @param  array<string, mixed>  $schema */
    private function php(array $schema): string
    {
        $slots = $this->slots($schema);
        $size = $this->size($schema);
        $lines = [
            '<?php',
            '',
            'namespace App\Modules\BlockTypes\Contracts;',
            '',
            '/**',
            ' * Generated by `php artisan dashflow:block-types` from block-types/'.$schema['key'].'/v'.$schema['contractVersion'].'/schema.json. Do not edit: change schema.json.',
            ' */',
            'final readonly class '.$this->className($schema),
            '{',
            "    public const KEY = '{$schema['key']}';",
            '',
            '    public const CONTRACT_VERSION = '.$schema['contractVersion'].';',
            '',
            '    public const DEFAULT_WIDTH = '.$size['default_width'].';',
            '',
            "    public const DEFAULT_HEIGHT = '{$size['default_height']}';",
            '',
        ];

        foreach ($slots as $slot) {
            $lines[] = '    public const SLOT_'.strtoupper($slot['key'])." = '{$slot['key']}';";
            $lines[] = '';
        }

        $lines[] = '    /** @var list<string> */';
        $lines[] = '    public const REQUIRED_SLOTS = '.$this->phpValue(array_values(array_map(fn (array $s): string => $s['key'], array_filter($slots, fn (array $s): bool => $s['required']))), 1).';';
        $lines[] = '';
        $lines[] = '    /** @var array<string, string> slot key => default aggregation */';
        $lines[] = '    public const DEFAULT_AGGREGATIONS = '.$this->phpValue($this->aggregations($schema), 1).';';
        $lines[] = '';
        $lines[] = '    /** @var array<string, array{key: string, label: string, required: bool, value_type: string, cardinality: string, field_roles: list<string>}> */';
        $lines[] = '    public const SLOTS = '.$this->phpValue(array_column($slots, null, 'key'), 1).';';
        $lines[] = '}';
        $lines[] = '';

        return implode("\n", $lines);
    }

    /**
     * @param  array<string, array<string, mixed>>  $schemas
     */
    private function typescript(array $schemas): string
    {
        $lines = [
            '// Generated by `php artisan dashflow:block-types`. Do not edit: change block-types/{key}/v{N}/schema.json.',
            '// The shape is what `GET /api/v1/block-types` returns.',
            '',
            ...$this->tsUnion('BlockTypeValueType', BlockTypeVocabulary::VALUE_TYPES),
            ...$this->tsUnion('BlockTypeCardinality', BlockTypeVocabulary::CARDINALITIES),
            ...$this->tsUnion('BlockTypeFieldRole', BlockTypeVocabulary::FIELD_ROLES),
            ...$this->tsUnion('BlockTypeAggregation', BlockTypeVocabulary::AGGREGATIONS),
            ...$this->tsUnion('BlockTypeHeight', BlockTypeVocabulary::HEIGHTS),
            '',
            'export interface BlockTypeSlot {',
            '    key: string;',
            '    label: string;',
            '    required: boolean;',
            '    value_type: BlockTypeValueType;',
            '    cardinality: BlockTypeCardinality;',
            '    field_roles: BlockTypeFieldRole[];',
            '}',
            '',
            'export interface BlockTypeSize {',
            '    default_width: number;',
            '    min_width: number;',
            '    max_width: number;',
            '    default_height: BlockTypeHeight;',
            '    min_height: BlockTypeHeight;',
            '    max_height: BlockTypeHeight;',
            '}',
            '',
            'export interface BlockType {',
            '    key: string;',
            '    contract_version: number;',
            '    title: string;',
            '    slots: BlockTypeSlot[];',
            '    size: BlockTypeSize;',
            '    default_aggregations: Record<string, BlockTypeAggregation>;',
            '}',
        ];

        foreach ($schemas as $schema) {
            $const = lcfirst(str_replace(' ', '', ucwords(str_replace('-', ' ', (string) $schema['key'])))).'V'.$schema['contractVersion'];
            $name = str_replace(' ', '', ucwords(str_replace('-', ' ', (string) $schema['key'])));
            $keys = array_map(fn (array $s): string => $s['key'], $this->slots($schema));

            $lines[] = '';
            array_push($lines, ...$this->tsUnion("{$name}SlotKey", $keys));
            $lines[] = '';
            $lines[] = "export const {$const}: BlockType = {";
            $lines[] = "    key: '{$schema['key']}',";
            $lines[] = "    contract_version: {$schema['contractVersion']},";
            $lines[] = '    title: '.$this->tsString((string) ($schema['title'] ?? '')).',';
            $lines[] = '    slots: [';
            foreach ($this->slots($schema) as $slot) {
                $lines[] = '        {';
                $lines[] = "            key: '{$slot['key']}',";
                $lines[] = '            label: '.$this->tsString($slot['label']).',';
                $lines[] = '            required: '.($slot['required'] ? 'true' : 'false').',';
                $lines[] = "            value_type: '{$slot['value_type']}',";
                $lines[] = "            cardinality: '{$slot['cardinality']}',";
                $lines[] = '            field_roles: ['.implode(', ', array_map(fn (string $r): string => "'{$r}'", $slot['field_roles'])).'],';
                $lines[] = '        },';
            }
            $lines[] = '    ],';
            $lines[] = '    size: {';
            foreach ($this->size($schema) as $field => $value) {
                $lines[] = "        {$field}: ".(is_int($value) ? $value : "'{$value}'").',';
            }
            $lines[] = '    },';
            $aggregations = $this->aggregations($schema);

            if ($aggregations === []) {
                // The formatter keeps an empty object on one line.
                $lines[] = '    default_aggregations: {},';
            } else {
                $lines[] = '    default_aggregations: {';
                foreach ($aggregations as $slot => $aggregation) {
                    $lines[] = "        {$slot}: '{$aggregation}',";
                }
                $lines[] = '    },';
            }
            $lines[] = '};';
        }

        $lines[] = '';

        return implode("\n", $lines);
    }

    /**
     * A union alias laid out as the formatter would: on one line when it fits in 80 columns, else one member per line.
     *
     * @param  list<string>  $values
     * @return list<string>
     */
    private function tsUnion(string $name, array $values): array
    {
        $members = array_map(fn (string $v): string => "'{$v}'", $values);
        $line = "export type {$name} = ".implode(' | ', $members).';';

        if (strlen($line) <= 80) {
            return [$line];
        }

        $lines = ["export type {$name} =", ...array_map(fn (string $m): string => "    | {$m}", $members)];
        $lines[count($lines) - 1] .= ';';

        return $lines;
    }

    private function tsString(string $value): string
    {
        return "'".str_replace(['\\', "'"], ['\\\\', "\\'"], $value)."'";
    }

    /**
     * @param  array<string, mixed>  $schema
     * @return list<array{key: string, label: string, required: bool, value_type: string, cardinality: string, field_roles: list<string>}>
     */
    private function slots(array $schema): array
    {
        $slots = [];

        foreach ((array) ($schema['slots'] ?? []) as $slot) {
            // A repeated slot (Story 5.8a) is the numbered slots the registry makes of it: `key_1` to `key_N`, the first as required as the declaration.
            $repeat = isset($slot['repeat']) && is_int($slot['repeat']) ? $slot['repeat'] : 1;

            for ($n = 1; $n <= $repeat; $n++) {
                $slots[] = [
                    'key' => (string) $slot['key'].(isset($slot['repeat']) ? "_{$n}" : ''),
                    'label' => (string) $slot['label'].(isset($slot['repeat']) ? " {$n}" : ''),
                    'required' => (bool) $slot['required'] && $n === 1,
                    'value_type' => (string) $slot['valueType'],
                    'cardinality' => (string) $slot['cardinality'],
                    'field_roles' => array_values(array_map('strval', (array) $slot['fieldRoles'])),
                ];
            }
        }

        return $slots;
    }

    /**
     * @param  array<string, mixed>  $schema
     * @return array{default_width: int, min_width: int, max_width: int, default_height: string, min_height: string, max_height: string}
     */
    private function size(array $schema): array
    {
        $size = (array) $schema['size'];

        return [
            'default_width' => (int) $size['defaultWidth'],
            'min_width' => (int) $size['minWidth'],
            'max_width' => (int) $size['maxWidth'],
            'default_height' => (string) $size['defaultHeight'],
            'min_height' => (string) $size['minHeight'],
            'max_height' => (string) $size['maxHeight'],
        ];
    }

    /**
     * @param  array<string, mixed>  $schema
     * @return array<string, string>
     */
    private function aggregations(array $schema): array
    {
        return array_map('strval', (array) ($schema['defaultAggregations'] ?? []));
    }

    /** A Pint-clean PHP literal: short arrays, single quotes, one entry per line, trailing commas. */
    private function phpValue(mixed $value, int $depth): string
    {
        if (is_array($value)) {
            if ($value === []) {
                return '[]';
            }

            if (array_is_list($value) && ! is_array($value[0])) {
                return '['.implode(', ', array_map(fn ($v): string => $this->phpValue($v, $depth), $value)).']';
            }

            $pad = str_repeat('    ', $depth + 1);
            $rows = [];
            foreach ($value as $key => $item) {
                $rows[] = $pad.(is_string($key) ? "'{$key}' => " : '').$this->phpValue($item, $depth + 1).',';
            }

            return "[\n".implode("\n", $rows)."\n".str_repeat('    ', $depth).']';
        }

        return match (true) {
            is_bool($value) => $value ? 'true' : 'false',
            is_int($value) => (string) $value,
            default => "'".str_replace(['\\', "'"], ['\\\\', "\\'"], (string) $value)."'",
        };
    }
}
